mapper.select:
SELECT user_id, balance, currency, version, created_at, updated_at
FROM user_account
WHERE user_id = #{userId}

mapper.update:
UPDATE user_account
SET balance = #{balance},
    version = version + 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND version = #{version}

UPDATE user_account
SET balance = balance - #{amount},
    version = version + 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND version = #{version}
  AND balance >= #{amount}

UPDATE user_account
SET balance = balance + #{amount},
    version = version + 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND version = #{version}
